func kIncreasing(arr []int, k int) int {
	save := 0
	for i, n := 0, len(arr); i < k && i < n; i++ {
		f := []int{}
		for j := i; j < n; j += k {
			v := arr[j]
			if p := sort.SearchInts(f, v+1); p < len(f) {
				f[p] = v
			} else {
				f = append(f, v)
			}
		}
		save += len(f)
	}
	return len(arr) - save
}

