const inf int = 1e9

func KuhnMunkres(wt [][]int) (sum int) {
	match := make([]int, len(wt)) // 右部点匹配了哪一个左部点
	la := make([]int, len(wt))
	for i, row := range wt {
		la[i] = -inf
		for _, v := range row {
			if v > la[i] {
				la[i] = v
			}
		}
	}
	lb := make([]int, len(wt))
	slack := make([]int, len(wt))
	for i := 1; i < len(wt); i++ {
		vb := make([]bool, len(wt))
		for j := 1; j < len(wt); j++ {
			slack[j] = inf
		}
		last := make([]int, len(wt)) // 右部点在交错树中的上一个右部点，用于倒推得到交错路
		y := 0
		match[0] = i // 一开始假设有一条 i-0 的匹配
		for {
			vb[y] = true
			x, nextY := match[y], 0
			delta := inf
			for j := 1; j < len(wt); j++ {
				if !vb[j] {
					if d := la[x] + lb[j] - wt[x][j]; d < slack[j] {
						slack[j] = d
						last[j] = y
					}
					if slack[j] < delta {
						delta = slack[j]
						nextY = j
					}
				}
			}
			// 当 delta=0 时，相当于沿着相等子图向下搜索一层
			// 当 delta>0 时，相当于直接回到最小边（新加入相等子图的边）处开始搜索
			if delta > 0 {
				for j := 0; j < len(wt); j++ {
					if vb[j] {
						la[match[j]] -= delta
						lb[j] += delta
					} else {
						slack[j] -= delta
					}
				}
			}
			y = nextY
			if match[y] == 0 {
				break
			}
		}
		// 倒推更新增广路
		for ; y > 0; y = last[y] {
			match[y] = match[last[y]]
		}
	}
	for w := 1; w < len(wt); w++ {
		sum += wt[match[w]][w]
	}
	return
}

func maxCompatibilitySum(students [][]int, mentors [][]int) int {
	m := len(students)
	wt := make([][]int, m+1)
	wt[0] = make([]int, m+1)
	for i := range wt[0] {
		wt[0][i] = -inf
	}
	for i, st := range students {
		wt[i+1] = make([]int, m+1)
		wt[i+1][0] = -inf
		for j, mt := range mentors {
			for k, v := range st {
				if v == mt[k] {
					wt[i+1][j+1]++
				}
			}
		}
	}
	return KuhnMunkres(wt)
}

LCP_81:
var k int

type seg []struct {
	l, r int
	to   [2]int
}

func (t seg) set(o, val int) {
	t[o].to[1] = t[o].to[0] ^ val
}

func (t seg) maintain(o int) {
	a, b, c := t[o<<1].to, t[o<<1|1].to, [2]int{}
	for i := 0; i < k; i++ {
		c[0] |= b[a[0]>>i&1] >> i & 1 << i
		c[1] |= b[a[1]>>i&1] >> i & 1 << i
	}
	t[o].to = c
}

func (t seg) build(a []int, k, o, l, r int) {
	t[o].l, t[o].r = l, r
	t[o].to[0] = 1<<k - 1
	if l == r {
		t.set(o, a[l-1])
		return
	}
	m := (l + r) >> 1
	t.build(a, k, o<<1, l, m)
	t.build(a, k, o<<1|1, m+1, r)
	t.maintain(o)
}

func (t seg) update(o, i, val int) {
	if t[o].l == t[o].r {
		t.set(o, val)
		return
	}
	m := (t[o].l + t[o].r) >> 1
	if i <= m {
		t.update(o<<1, i, val)
	} else {
		t.update(o<<1|1, i, val)
	}
	t.maintain(o)
}

func getNandResult(K int, arr []int, operations [][]int) (ans int) {
	k = K
	t := make(seg, len(arr)*4)
	t.build(arr, k, 1, 1, len(arr))
	for _, op := range operations {
		if op[0] == 0 {
			t.update(1, op[1]+1, op[2])
			continue
		}
		to := t[1].to
		x, y := op[1], op[2]
		for i := 0; i < k; i++ {
			var res int
			y := y >> i & 1
			y1 := to[y] >> i & 1 // 穿过 arr 一次
			if y1 == y { // 不变
				res = y
			} else if x == 1 || to[y1]>>i&1 == y1 {
				// 只穿过一次，或者穿过两次和穿过一次相同
				res = y1
			} else {
				res = y ^ x%2 // 奇变偶不变
			}
			ans ^= res << i
		}
	}
	return
}

