func minimumOperations(nums []int, start, goal int) int {
	vis := [1001]bool{}
	vis[start] = true
	q := []int{start}
	for step := 1; q != nil; step++ {
		tmp := q
		q = nil
		for _, v := range tmp {
			for _, num := range nums {
				for _, x := range []int{v + num, v - num, v ^ num} {
					if x == goal {
