func canDistribute(a []int, quantity []int) bool {
	// 预处理 quantity 每个子集的子集和
	m := 1 << len(quantity)
	sum := make([]int, m)
	for i, v := range quantity {
		bit := 1 << i
		for j := 0; j < bit; j++ {
			sum[bit|j] = sum[j] + v
		}
	}

	cnt := map[int]int{}
	for _, v := range a {
		cnt[v]++
	}
	n := len(cnt)

	// dp[i][j] 表示 cnt 的前 i 个元素能否满足集合为 j 的顾客
	dp := make([][]bool, n+1)
	for i := range dp {
		dp[i] = make([]bool, m)
		dp[i][0] = true
	}
	i := 0
	for _, c := range cnt {
		for j, ok := range dp[i] {
			if ok {
				dp[i+1][j] = true
				continue
			}
			for sub := j; sub > 0; sub = (sub - 1) & j { // 枚举 j 的子集 sub
				if sum[sub] <= c && dp[i][j^sub] { // 判断这 c 个数能否全部分给 sub，并且除了 sub 以外的 j 中的顾客也满足
					dp[i+1][j] = true
					break
				}
			}
		}
		i++
	}
	return dp[n][m-1]
}

