		cnt2 += tz
		x >>= tz
		for ; x%5 == 0; x /= 5 {
			cnt5++ // 因子 5 的个数
		}
		update(x)
	}
	cnt10 := min(cnt2, cnt5)
	for i := cnt10; i < cnt2; i++ {
		update(2) // 补上多拆出来的 2
	}
	for i := cnt10; i < cnt5; i++ {
