			return strictlyIncreasing(nums, i-1) || strictlyIncreasing(nums, i)
		}
	}
	return true
}

func strictlyIncreasing(a []int, i int) bool {
	a = append(append([]int(nil), a[:i]...), a[i+1:]...)
	return sort.SliceIsSorted(a, func(i, j int) bool { return a[i] <= a[j] })
}

