func (Bitset) Fix(i int) {
	if s[i] == flip {
		s[i] ^= 1
		cnt1++
	}
}

func (Bitset) Unfix(i int) {
	if s[i] != flip {
		s[i] ^= 1
		cnt1--
	}
}

func (Bitset) Flip() {
	flip ^= 1
	cnt1 = len(s) - cnt1
}

func (Bitset) All() bool  { return cnt1 == len(s) }
func (Bitset) One() bool  { return cnt1 > 0 }
func (Bitset) Count() int { return cnt1 }

func (Bitset) ToString() string {
	if flip == '1' {
		t := make([]byte, len(s))
		for i, ch := range s {
			t[i] = ch ^ 1
		}
		return string(t)
	}
	return string(s)
}

