func greatestLetter(s string) string {
	mask := uint64(0)
	for _, c := range s {
		mask |= 1 << (c - 'A')
	}
	mask &= mask >> ('a' - 'A')
	if mask == 0 {
		return ""
	}
	return string(byte('A' + bits.Len64(mask) - 1))
}

