func greatestLetter(s string) string {
	masks := [2]uint32{}
	for _, c := range s {
		masks[c>>5&1] |= 1 << (c & 31)
	}
	mask := masks[0] & masks[1]
	if mask == 0 {
		return ""
	}
	return string(byte('A' + bits.Len32(mask) - 2))
}

